checks={key:read(file) for key,file in {'native':'audit-native-faceted.json','capture':'audit-pixels-native.json','receipts':'audit-receipts.json','transparency':'audit-transparency.json','alpha':'audit-alpha-exceptions.json','approvedReference':'audit-selected-reference.json','publication':'audit-published-atlases.json'}.items()}
passed=all(value['passed'] for value in checks.values());capture=checks['capture']['native'];publication=checks['publication']['published'];manifest=json.loads((PRODUCTION/'library.json').read_text());paths=sorted({d['image'] for a in manifest['objects'] for c in a['clips'] for d in c['directions'].values()})
report={'passed':passed,'sourceBlendSHA256':checks['native']['projectSHA256'],'canonicalBlendSHA256':sha(PRODUCTION/'source/blender/sushi-loop-world-library.blend'),'nativeObjects':len(capture['assets']),'flatObjects':checks['publication']['flatArtwork']['count'],'nativeFrames':capture['frames'],'runtimeObjects':len(publication['objects']),'frameFacingContexts':publication['frameFacingContexts'],'atlasFiles':len(paths),'byteExactUniformWholeFrameSamples':publication['wholeFrameUniformSampleVerified'],'maximumAtlasDimension':publication['maximumAtlasDimension'],'textureLimit':8192,'adaptiveAtlasGroups':len(publication['adaptiveColumnGroups']),'alphaByteIdenticalFrames':capture['alphaIdenticalFrames'],'tinyAlphaDifferenceFrames':len(checks['alpha']['frames']),'largeAlphaDifferenceFrames':capture['largeAlphaChangeFrames'],'flatArtworkUnchanged':checks['publication']['flatArtwork']['unchanged'],'auditReports':{key:{'passed':value['passed']} for key,value in checks.items()},'atlasSHA256':{path:sha(PRODUCTION/path) for path in paths},'notes':['All native runtime cells equal a LANCZOS sample of the complete authored 4x canvas at the declared 2x frame size. No silhouette fitting or per-frame resize was introduced.','Eight dock-cover groups use 5 columns: 7360x4224 atlases, 1472x1408 frames.','Five translucent-ray frames have 2–7 changed source pixels, maximum 5/255 alpha; all bounds unchanged.','This is source/capture/resource evidence; engine imports, browser playback and Android-device performance are separate checks.']}
report['passed']=passed and report['sourceBlendSHA256']==report['canonicalBlendSHA256'] and report['nativeObjects']==104 and report['flatObjects']==13 and report['runtimeObjects']==117 and report['nativeFrames']==9390 and report['byteExactUniformWholeFrameSamples']==9390 and report['frameFacingContexts']==11082 and report['atlasFiles']==967 and report['maximumAtlasDimension']<=8192 and report['flatArtworkUnchanged']
(HERE/'audit-summary.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:v for k,v in report.items() if k!='atlasSHA256'}))
